draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Morrie
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // Book
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Tuesdays with Morrie', W/2, H/2 - 80);

  // Lessons
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Forgive', W/2 - 100, H/2 + 30);

  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Love', W/2 + 100, H/2 + 30);

  // Dying and Living
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 - 50 + 50 * Math.sin(t), H/2 + 150);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Dying', W/2 - 50 + 50 * Math.sin(t), H/2 + 170);

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 + 50 - 50 * Math.sin(t), H/2 + 150);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Living', W/2 + 50 - 50 * Math.sin(t), H/2 + 170);

  ctx.restore();
}
